// Renders a page of the application from the partials and fragments in this folder.
// The pages themselves (report.html and Src/Pages/*.html) are generated by `npm run build:pages`.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const templateDirectory = path.dirname(fileURLToPath(import.meta.url));

function ReadTemplate(relativePath) {
  return fs
    .readFileSync(path.join(templateDirectory, relativePath), "utf8")
    .replace(/\r\n/g, "\n")
    .trimEnd();
}

/**
 * Replaces the {{name}} placeholders of a template. A placeholder without a value is an error.
 */
function Fill(template, values) {
  const filled = template.replace(/\{\{(\w+)\}\}/g, (placeholder, name) => {
    if (!(name in values)) {
      throw new Error(`No value for the placeholder ${placeholder}.`);
    }
    return values[name];
  });
  return filled;
}

/**
 * The paths from a page to the shared files. The report page is in the root folder, the other pages are in Src/Pages.
 */
const PREFIXES = {
  root: {
    css: "./Src/CSS/",
    dist: "./Dist/",
    script: "Dist/",
    pages: "./Src/Pages/",
    home: "./report.html",
    docs: "./Docs/",
  },
  pages: {
    css: "../CSS/",
    dist: "../../Dist/",
    script: "../../Dist/",
    pages: "../Pages/",
    home: "../../report.html",
    docs: "../../Docs/",
  },
};

/**
 * The buttons below the navigation bar, see partials/buttons.html.
 */
const buttons = Object.fromEntries(
  ReadTemplate("partials/buttons.html")
    .split(/<!-- @button ([\w-]+) -->\n/)
    .slice(1)
    .reduce((pairs, part, index, parts) => {
      if (index % 2 === 0) {
        pairs.push([part, parts[index + 1].trim()]);
      }
      return pairs;
    }, []),
);

function RenderButton(button) {
  const [name, values] = Array.isArray(button) ? button : [button, {}];
  if (!(name in buttons)) {
    throw new Error(`Unknown button: ${name}`);
  }
  return Fill(buttons[name], values);
}

/**
 * The entries of the plots menu. The page that is shown is marked as active.
 */
const PLOT_MENU = [
  {
    page: "performance_profile",
    label: '<i class="bi bi-graph-up-arrow"></i> Performance Profile',
  },
  {
    page: "solver_time_all",
    label: '<i class="bi bi-bar-chart-line-fill"></i> Solver Time per Solver',
  },
  {
    page: "solver_time",
    label: '<i class="bi bi-graph-up"></i> Solver Time per Instance',
  },
  "separator",
  {
    page: "number_of_nodes",
    label: '<i class="bi bi-bar-chart-line"></i> Number of Nodes',
  },
  {
    page: "number_of_iterations",
    label: '<i class="bi bi-bar-chart-line"></i> Number of Iterations',
  },
  {
    page: "termination_status",
    label: '<i class="bi bi-bar-chart-line"></i> Termination Status',
  },
  "separator",
  {
    page: "solution_quality",
    label: '<i class="bi bi-bar-chart-line-fill"></i> Solution Quality',
  },
  {
    page: "solution_time",
    label: '<i class="bi bi-circle-square"></i> Solution Time',
  },
];

const PLOT_PAGES = new Set(
  PLOT_MENU.filter((entry) => entry !== "separator").map((entry) => entry.page),
);

/**
 * A link of the navigation bar. The link to the page that is shown is not a link but is marked as active.
 */
function RenderNavLink(label, href, isActive) {
  const content = `<li class="nav-item">`;
  return isActive
    ? `${content}<span class="nav-link active" aria-current="page">${label}</span></li>`
    : `${content}<a class="nav-link" href="${href}">${label}</a></li>`;
}

function RenderNavItems(activePage, prefixes) {
  const menuItems = PLOT_MENU.map((entry) => {
    if (entry === "separator") {
      return "<hr />";
    }
    return entry.page === activePage
      ? `<li><span class="dropdown-item active">${entry.label}</span></li>`
      : `<li><a class="dropdown-item" href="${prefixes.pages}${entry.page}.html">${entry.label}</a></li>`;
  }).join("");

  return [
    RenderNavLink(
      '<i class="bi bi-file-spreadsheet"></i> Table',
      prefixes.home,
      activePage === "report",
    ),
    `<li class="nav-item dropdown"><a class="nav-link dropdown-toggle${
      PLOT_PAGES.has(activePage) ? " active" : ""
    }" id="navbarDropdownMenuLink" role="button" data-bs-toggle="dropdown" aria-expanded="false"><i class="bi bi-bar-chart-steps"></i> Plots</a><ul class="dropdown-menu mb-2" aria-labelledby="navbarDropdownMenuLink">${menuItems}</ul></li>`,
    RenderNavLink(
      '<i class="bi bi-view-stacked"></i> Compare Solvers',
      `${prefixes.pages}compare_solvers.html`,
      activePage === "compare_solvers",
    ),
  ].join("");
}

/**
 * Sets the theme before the first paint. Keep it in step with Src/Scripts/Theme.ts.
 */
const THEME_SCRIPT = `(function () {
        var theme = null;
        try {
          theme = localStorage.getItem("theme");
        } catch (e) {}
        if (theme !== "light" && theme !== "dark") {
          theme = window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
        }
        document.documentElement.setAttribute("data-bs-theme", theme);
      })();`;

function RenderHead(page, prefixes) {
  const manifest = page.manifest
    ? '\n    <!-- Manifest for PWA -->\n    <link rel="manifest" href="manifest.json" />'
    : "";
  return `<head>
    <meta charset="UTF-8" />
    <meta http-equiv="X-UA-Compatible" content="IE=edge" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <meta name="color-scheme" content="light dark" />
    <meta name="theme-color" content="#ffffff" />
    <!-- Theme, set before the first paint -->
    <script>
      ${THEME_SCRIPT}
    </script>
    <meta
      name="description"
      content="Visualize, interact, verify, and analyze benchmarking data for optimization solvers."
    />${manifest}
    <!-- Title and icon -->
    <title id="ReportTitle">${page.title}</title>
    <link rel="icon" href="${prefixes.css}tab_icon.png" />
    <!-- Styling -->
    <link href="${prefixes.dist}main.css" rel="stylesheet" />
    <!-- The content is shown by a script, without one it is shown at once -->
    <noscript>
      <style>
        body > :not(nav, hr) {
          opacity: 1;
        }
      </style>
    </noscript>
  </head>`;
}

/**
 * The body below the line that follows the buttons: a fragment of the page, or the chart.
 */
function RenderContent(content) {
  const chartTools = ReadTemplate("partials/chart-tools.html");
  if (content.fragment) {
    return ReadTemplate(`fragments/${content.fragment}.html`)
      .replace("<!-- @chart-tools -->", chartTools)
      .trim();
  }
  const chart = `${chartTools}
    <div id="chartContainer">
      <canvas id="myChart" class="chart">
        <!-- Content created with Chart.js will be displayed here. -->
      </canvas>
    </div>`;
  const statistics = `<div id="statisticsTable">
      <!-- statistics table element will be created here. -->
    </div>`;
  return content.statistics ? `${chart}\n\n    ${statistics}` : chart;
}

/**
 * Renders the HTML of a page. The result is not formatted, see scripts/build-pages.mjs.
 *
 * @param page - The page, see pages.mjs.
 */
export function RenderPage(page) {
  const prefixes = PREFIXES[page.location];
  const navigation = Fill(ReadTemplate("partials/nav.html"), {
    ...prefixes,
    navItems: RenderNavItems(page.name, prefixes),
    navExtra:
      page.location === "root" ? ReadTemplate("partials/nav-demo.html") : "",
  });
  const alert = ReadTemplate("partials/alert.html");
  const emptyState = ReadTemplate("partials/empty-state.html");
  const controls = page.controls
    ? `\n\n    ${ReadTemplate(`fragments/${page.controls}.html`).trim()}\n`
    : "";
  // The report page has no empty lines around its content.
  const gap = page.location === "root" ? "\n" : "\n\n";

  return `<!DOCTYPE html>
<html lang="en">
  ${RenderHead(page, prefixes)}

  <body>
    <a class="visually-hidden-focusable" href="#buttonContainer">Skip to content</a>
    ${navigation}
    ${alert}
    <div id="buttonContainer" class="d-flex flex-wrap justify-content-start gap-2">
      ${page.buttons.map(RenderButton).join("\n")}
    </div>${controls}
    <hr />
    ${emptyState}${gap}    ${RenderContent(page.content)}${gap}    <!-- Main script -->
    <script id="MainFunction" src="${prefixes.script}bundle.js"></script>
  </body>
</html>
`;
}
